


export type CreditNoteCorrectionRequestInput = ({ /** Amount to credit, no more than the source invoice line is worth, in the invoice currency. */ "amount_money"?: { /** Amount in the currency's minor unit, such as cents for USD. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 0. */ "amount": string; /** ISO 4217 currency code for this amount. minLength: 3. maxLength: 3. pattern: ^[A-Z]{3}$. Example: "USD". */ "currency": string; }; /** Units to credit, no more than the source invoice line carries. Whole-number quantity; fractional quantities are not supported. Use an exact numeric string, not a floating-point number. Format: int64. */ "quantity"?: string; /** quantity credits whole units and requires quantity. amount credits a named figure and requires amount_money. The two are mutually exclusive. */ "type": "quantity" | "amount"; }) & ((({ "type": "quantity"; "quantity": unknown; }) & ({ "amount_money"?: never })) | (({ "type": "amount"; "amount_money": unknown; }) & ({ "quantity"?: never })));
